// zzProbe runs after the external-agent tests (source/name order) to observe
// whether their mock registrations leaked into the process-global registry.
func TestZZProbeRegistryLeak(t *testing.T) {
	names := agent.StringList()
	joined := strings.Join(names, ",")
	t.Logf("registry after external tests: %s", joined)

	for _, leaked := range []string{"ext-available-test", "ext-installed-test"} {
		if strings.Contains(joined, leaked) {
			t.Errorf("LEAKED into global registry: %s", leaked)
		}
	}

	// Does the leaked agent's binary still exist? Exercise the same call
	// runAgentList makes.
	installed := GetAgentsWithHooksInstalled(context.Background())
	t.Logf("GetAgentsWithHooksInstalled -> %v", installed)
}

